// cards_web.js — the web version's own card balance, applied over the generated cards.js (which follows the UEFN
// card_db.verse and is regenerated by conv_db.py; the UEFN island keeps its values). Patches are by card id:
// every field given replaces the card's own (new fx() = the effect is gone).
'use strict';

const CardWebPatches = {
  // 応龍 マナ10 6/8 叫び:他のモンスターを全て破壊
  189: { Cost: 10, Atk: 6, Hp: 8 },
  // 龍 マナ8 6/6 叫び:他のモンスター全てに3ダメージ (no evolve effect any more: the usual +2/+2)
  188: { Cost: 8, Atk: 6, Hp: 6, Evo: new fx(), EvoAtk: 2, EvoHp: 2 },
  // がしゃどくろ マナ8 6/6 挑発 叫び:他のモンスターすべてに2ダメージ
  148: { Cost: 8, Atk: 6, Hp: 6, Taunt: true },
  // ジンジャーガール マナ2 1/2 叫び:自分のプレイヤーのHPを1回復
  214: { Cost: 2, Atk: 1, Hp: 2 },
  // ひつじ マナ4 2/4 叫び:自分のプレイヤーのHPを2回復 / 進化時:自分のプレイヤーのHPを2回復
  54: { Cost: 4, Atk: 2, Hp: 4, TurnEnd: new fx(), Cry: FxN(fx_kind.HealHero, 2), Evo: FxN(fx_kind.HealHero, 2) },
  // リボンバット マナ3 3/5 吸血 叫び:自分の味方モンスター1体を破壊する
  302: { Cost: 3, Atk: 3, Hp: 5, Rush: false, Drain: true, Cry: Fx0(fx_kind.DestroyAlly) },
  // ワルル マナ3 2/2 叫び:場にあるモンスターまたはアミュレットを持ち主の手札に戻す
  304: { Cost: 3, Atk: 2, Hp: 2, Deadly: false, SelfDmg: 0, Cry: Fx0(fx_kind.BounceAny) },
  // ミツメヨクチ マナ6 4/4 ターン終了時:復讐状態なら+4/+4を得る
  367: { Cost: 6, Atk: 4, Hp: 4, Cry: new fx(), Death: new fx(), TurnEnd: new fx({ K: fx_kind.BuffSelf, N: 4, M: 4, Cond: 2 }) },
};

// (kit.js MakeCardLib) the card list with the web patches
function CardWebPatch(DB) {
  for (const Id in CardWebPatches) {
    const D = DB[Id];
    if (D) Object.assign(D, CardWebPatches[Id]);
  }
  // the collection's cost order follows the new costs (the order inside a cost stays)
  CardOrderCost.sort((A, B) => ((DB[A] ? DB[A].Cost : 0) - (DB[B] ? DB[B].Cost : 0)));
  return DB;
}
